# COPY — generated by build_repo_mirror.R. Do not edit here. Working copy: data_workspace_2026-07/ch3_pipeline_restored/scripts/64r_backbench_frontbench_2020_2025.R
# 64r_backbench_frontbench_2020_2025.R
#
# Extends the backbench/frontbench split (64q, 1979-2019 via Blumenau's own
# role fields) to 2020-2025, closing the coverage gap flagged when the split
# was promoted to Figure 3.3. PJ, 7 Sep: "we do need the whole date range
# too difficult with the split?" — not too difficult: the Hansard API's
# `member_id` uses the SAME numeric ID scheme as UK Parliament's Members API
# (confirmed directly, e.g. id 4070 = Matt Hancock in both), which has full
# government/opposition post history with dates
# (members-api.parliament.uk/api/Members/{id}/Biography).
#
# METHOD: reproduce the EXACT same 2020-2025 sample as 64o (same seed, same
# filter — the same speeches already scored for the headline series), pull
# each unique speaker's post history ONCE (949 unique member_ids, cached as
# raw JSON per member for replicability), then flag each speech as
# frontbench if the speaker held ANY government or opposition post on that
# exact date.
#
# OUTPUT: online_appendix/ch3_backbench_frontbench_2020_2025.csv (same
# schema as 64q's 1979-2019 output, appended to it in 64s)
#         sources_raw/members_api_biography_cache/{member_id}.json

suppressMessages({library(dplyr); library(readr); library(stringr); library(purrr); library(jsonlite)})

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT   <- .ROOT
WKBD_ROOT <- normalizePath(file.path(PROJECT, "..", ".."))
CACHE_DIR <- file.path(WKBD_ROOT, "sources_raw/members_api_biography_cache")
dir.create(CACHE_DIR, showWarnings = FALSE, recursive = TRUE)

# ============================================================
# 1. REPRODUCE the exact 2020-2025 sample (same as 64o)
# ============================================================
chamber <- read_csv(file.path(WKBD_ROOT, "sources_raw/hansard_api_pull_2020_2025/hansard_contributions_2020_2025_dedup.csv"), show_col_types = FALSE)
wh <- read_csv(file.path(WKBD_ROOT, "sources_raw/hansard_api_pull_2020_2025/hansard_contributions_westhall_2020_2025.csv"), show_col_types = FALSE)
combined <- bind_rows(chamber, wh) |>
  mutate(date = as.Date(date), year = as.integer(format(date, "%Y"))) |>
  filter(year >= 2020, year <= 2025, !is.na(text), nchar(text) > 300)

set.seed(42)
samp <- combined |> group_by(year) |> group_modify(~ slice_sample(.x, n = min(1500, nrow(.x)))) |> ungroup()
cat(sprintf("Sample: %d speeches, %d unique speakers\n", nrow(samp), n_distinct(samp$member_id)))

# ============================================================
# 2. FETCH POST HISTORY per unique member (cached)
# ============================================================
ids <- unique(samp$member_id[!is.na(samp$member_id)])
cat(sprintf("Fetching biography for %d members...\n", length(ids)))

get_bio <- function(id) {
  cache_f <- file.path(CACHE_DIR, sprintf("%s.json", id))
  if (file.exists(cache_f)) return(fromJSON(cache_f, simplifyVector = FALSE))
  url <- sprintf("https://members-api.parliament.uk/api/Members/%s/Biography", id)
  res <- tryCatch({
    r <- httr::GET(url, httr::timeout(20))
    if (httr::status_code(r) != 200) return(NULL)
    j <- httr::content(r, as = "text", encoding = "UTF-8")
    write(j, cache_f)
    fromJSON(j, simplifyVector = FALSE)
  }, error = function(e) NULL)
  Sys.sleep(0.15)
  res
}

t0 <- Sys.time()
bios <- vector("list", length(ids))
names(bios) <- as.character(ids)
for (i in seq_along(ids)) {
  bios[[i]] <- get_bio(ids[i])
  if (i %% 100 == 0) cat(sprintf("  %d/%d (%.1f min)\n", i, length(ids), as.numeric(Sys.time()-t0, units="mins")))
}
cat(sprintf("Done fetching, %.1f min\n", as.numeric(Sys.time()-t0, units="mins")))

# ============================================================
# 3. BUILD interval table: member_id, start, end (any govt/opposition post)
# ============================================================
intervals <- map_dfr(names(bios), function(id) {
  b <- bios[[id]]
  if (is.null(b) || is.null(b$value)) return(NULL)
  posts <- c(b$value$governmentPosts, b$value$oppositionPosts)
  if (length(posts) == 0) return(NULL)
  map_dfr(posts, function(p) {
    tibble(member_id = as.numeric(id),
           start = as.Date(substr(p$startDate, 1, 10)),
           end = if (is.null(p$endDate)) as.Date("2030-01-01") else as.Date(substr(p$endDate, 1, 10)))
  })
})
cat(sprintf("Post intervals: %d rows across %d members\n", nrow(intervals), n_distinct(intervals$member_id)))

# Fast lookup: split intervals into a list keyed by member_id (hash lookup,
# not a fresh table filter per row) — 9000 rows x re-filtering a 2-5k row
# table each time would be far too slow.
intervals_by_member <- split(intervals[, c("start", "end")], intervals$member_id)

is_frontbench_on <- function(mid, dt) {
  key <- as.character(mid)
  if (is.na(mid) || is.null(intervals_by_member[[key]])) return(FALSE)
  iv <- intervals_by_member[[key]]
  any(iv$start <= dt & iv$end >= dt)
}

samp <- samp |> mutate(is_frontbench = map2_lgl(member_id, date, is_frontbench_on))
cat(sprintf("Frontbench share of sample: %.1f%%\n", 100*mean(samp$is_frontbench)))

# ============================================================
# 4. SCORE — identical dictionary/method
# ============================================================
career_terms <- c(
  "my role", "my position", "my appointment", "my department",
  "my portfolio", "my responsibilities", "my tenure", "my office",
  "my capacity", "my ministerial", "my shadow", "my career",
  "as minister", "as secretary of state", "as chancellor",
  "as home secretary", "as foreign secretary", "as prime minister"
)
policy_terms <- c(
  "my constituents", "my constituency", "people in my",
  "the evidence", "the research shows", "the data",
  "the public", "communities", "families",
  "workers", "businesses", "this policy", "the policy",
  "the bill", "the legislation", "the government must",
  "we must", "we should", "we need to"
)
score_speech <- function(text, terms) sum(str_count(tolower(text), fixed(terms)))

scored <- samp |>
  mutate(
    n_words = str_count(text, "\\S+"),
    n_career = map_int(text, score_speech, career_terms),
    n_policy = map_int(text, score_speech, policy_terms),
    self_ratio = (n_career + 0.5) / (n_career + n_policy + 1)
  ) |>
  filter(n_words >= 50)

annual <- scored |>
  group_by(year, is_frontbench) |>
  summarise(n = n(), ratio = mean(self_ratio), .groups = "drop") |>
  tidyr::pivot_wider(names_from = is_frontbench, values_from = c(n, ratio),
                     names_glue = "{ifelse(is_frontbench=='TRUE','frontbench','backbench')}_{.value}") |>
  rename(n_backbench = backbench_n, backbench_ratio = backbench_ratio,
         n_frontbench = frontbench_n, frontbench_ratio = frontbench_ratio) |>
  mutate(fb_share = n_frontbench / (n_frontbench + n_backbench)) |>
  arrange(year)

cat("\n=== 2020-2025 backbench/frontbench split ===\n")
print(as.data.frame(annual), row.names = FALSE)

OUT <- file.path(WKBD_ROOT, "online_appendix/ch3_backbench_frontbench_2020_2025.csv")
write_csv(annual, OUT)
cat("\nSaved:", OUT, "\n")
